import{_ as e,o as r,c as a,a2 as o}from"./chunks/framework.BEUshCVJ.js";const u=JSON.parse('{"title":"练习模式","description":"","frontmatter":{},"headers":[],"relativePath":"zh/guide/practice.md","filePath":"zh/guide/practice.md","lastUpdated":1793061719000}'),d={name:"zh/guide/practice.md"};function i(l,t,n,c,s,h){return r(),a("div",null,[...t[0]||(t[0]=[o('<h1 id="练习模式" tabindex="-1">练习模式 <a class="header-anchor" href="#练习模式" aria-label="Permalink to &quot;练习模式&quot;">​</a></h1><p>本页介绍如何用 MeetCue 演练面试或会议。它会朗读问题，像真实会议一样给出提示，结束后生成复盘报告。</p><div class="tip custom-block"><p class="custom-block-title">第一次使用？</p><p><a href="/meetcue/zh/guide/mock-interview">模拟面试</a>一步步带你完成一次完整的练习，内置软件工程和网络安全与 AI 方向的示例面试。</p></div><h2 id="导入题目" tabindex="-1">导入题目 <a class="header-anchor" href="#导入题目" aria-label="Permalink to &quot;导入题目&quot;">​</a></h2><p>在托盘菜单中打开 <strong>模拟面试…</strong>，或点面板上的 <strong>试试模拟面试</strong>。选择一个内置示例面试，或选择自己的文件。文件在本机处理，只有问题文本和你的回答会发送给模型。</p><table tabindex="0"><thead><tr><th>类型</th><th>格式</th><th>说明</th></tr></thead><tbody><tr><td>会议字幕</td><td><code>.srt</code>、<code>.vtt</code>、<code>.txt</code></td><td>说话人取自“名字：”前缀或 VTT 的 <code>&lt;v 名字&gt;</code> 标签。导入时选择哪个说话人是你。</td></tr><tr><td>问题列表</td><td><code>.txt</code>、<code>.md</code>、<code>.csv</code></td><td>每行一题；以 <code>#</code> 开头的行开始一个分组。CSV 的列见<a href="/meetcue/zh/reference/file-formats">文件格式</a>。</td></tr></tbody></table><p>没有说话人信息的字幕会由模型把每句标为提问或回答，你确认结果后再开始。</p><p>导入后的预览表可以编辑、删除、调整顺序、随机打乱，或只抽取若干题。</p><p>内置示例也放在仓库的 <a href="https://github.com/Amazingkenneth/meetcue/tree/HEAD/samples/practice" target="_blank" rel="noreferrer">samples/practice</a> 目录下，对应的职位描述在 <a href="https://github.com/Amazingkenneth/meetcue/tree/HEAD/samples/materials" target="_blank" rel="noreferrer">samples/materials</a>。</p><h2 id="提问的声音" tabindex="-1">提问的声音 <a class="header-anchor" href="#提问的声音" aria-label="Permalink to &quot;提问的声音&quot;">​</a></h2><p>问题由 Windows 语音朗读。在模拟面试窗口的第一步，可以分别为中文和英文选择语音，点 <strong>试听</strong> 听效果，并调整朗读语速。选择 <strong>Windows 提供的第一个语音</strong> 即保持 MeetCue 原来的选择。更多语音可在 Windows 设置 › 时间和语言 › 语音 中安装。</p><h2 id="语音转文字" tabindex="-1">语音转文字 <a class="header-anchor" href="#语音转文字" aria-label="Permalink to &quot;语音转文字&quot;">​</a></h2><p>问题总是用 Windows 自带的语音朗读出来，与真实会议一样。两个开关决定哪些内容转成文字：</p><ul><li><strong>问题语音转文字</strong>（默认开启）：朗读的问题从系统声音采集，由语音识别供应商识别，与真实会议完全一样。你看到的延迟就是会议中的延迟。关闭后，问题文本在一段识别延迟之后直接交给要点模型；这段延迟取自你最近一次延迟探测的结果。这样可以省下对方声音的识别费用。模型本身的延迟是真实的。</li><li><strong>我的回答语音转文字</strong>（默认开启）：识别你的麦克风，用于要点打勾和复盘。再关闭它就完全不产生语音识别费用，但也就没有打勾和部分复盘指标。</li></ul><h2 id="节奏与追问" tabindex="-1">节奏与追问 <a class="header-anchor" href="#节奏与追问" aria-label="Permalink to &quot;节奏与追问&quot;">​</a></h2><ul><li>问题列表：MeetCue 提一个问题后等待。20 秒内没有开口，面板会轻提示。停顿 3 秒或按 <code>Ctrl+Alt+Enter</code> 表示答完。</li><li>开启追问后，MeetCue 会按一定概率（默认 30%）根据你的回答提一个简短的追问。</li><li>会议字幕：其他说话人的句子按原时间轴播放，较长的空白压缩到 2 秒。播放到你的句子时暂停等你回答，原句作为复盘里的参考回答。</li><li><code>Ctrl+Alt+]</code> 跳过当前题，<code>Ctrl+Alt+Space</code> 暂停或继续。练习窗口和面板上的 <strong>再问一遍</strong> 会从头重读当前这道题，并丢弃已经开始的回答。</li><li>问题还在朗读时你开口说话，朗读会停止。只有真正的说话才算：咳嗽、口头禅，或者把问题本身听错的词都不会打断朗读。可以用 <strong>我开口时停止朗读</strong> 关闭这一行为。</li></ul><h2 id="提示难度" tabindex="-1">提示难度 <a class="header-anchor" href="#提示难度" aria-label="Permalink to &quot;提示难度&quot;">​</a></h2><p>开始前选择，练习中也可以切换：</p><ol><li><strong>完整</strong>：与会议模式相同。</li><li><strong>只显示主词</strong>：只显示加粗的主词，不显示补充词和示例回答。</li><li><strong>延迟显示</strong>：问题结束几秒后才出现提示。</li><li><strong>关闭</strong>：提示只出现在复盘里。</li></ol><p>建议逐档降低，直到不看提示也能回答。</p><h2 id="review-report" tabindex="-1">复盘报告 <a class="header-anchor" href="#review-report" aria-label="Permalink to &quot;复盘报告 {#review-report}&quot;">​</a></h2><p>练习结束后，复盘报告按题和整场列出：</p><table tabindex="0"><thead><tr><th>指标</th><th>含义</th></tr></thead><tbody><tr><td>开口用时</td><td>从问题结束到识别出你的第一个字</td></tr><tr><td>回答时长</td><td>从你开口到答完</td></tr><tr><td>要点覆盖率</td><td>打勾的要点数 / 要点总数</td></tr><tr><td>口头禅</td><td>中文“嗯、啊、那个、就是、然后”，英文“um、uh、like、you know”；可在设置中修改</td></tr><tr><td>语速</td><td>中文按字 / 分钟，英文按词 / 分钟</td></tr><tr><td>反馈</td><td>有参考回答时给出 3 条简短反馈：漏掉的要点、可改进的表达、做得好的地方</td></tr></tbody></table><p>报告可以导出为 Markdown。历次练习保存在设置文件夹下的 <code>practice</code> 文件夹中，复盘页可以查看历次趋势。</p>',24)])])}const g=e(d,[["render",i]]);export{u as __pageData,g as default};
